using System;using System.Diagnostics;using System.Linq;using System.IO;using PMStudio;
class B{static void Main(string[] a){foreach(bool hollow in new[]{false,true}){Project p=hollow?Examples.Circle(true):Examples.Rectangle();Engine.Analyze(p);double[] ms=new double[3];int gc=GC.CollectionCount(0);Analysis r=null;for(int i=0;i<3;i++){var s=Stopwatch.StartNew();r=Engine.Analyze(p);ms[i]=s.Elapsed.TotalMilliseconds;}Array.Sort(ms);Console.WriteLine((hollow?"hollow":"rectangle")+" median_ms="+ms[1].ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+" gc0="+(GC.CollectionCount(0)-gc));File.WriteAllText(Path.Combine(a[0],hollow?"hollow-result.json":"rectangle-result.json"),Files.Json(r));}}}
